param(
  [string]$ProjectRoot=(Get-Location).Path,
  [string]$VpsHost="root@178.104.184.138",
  [string]$SshKey="$env:USERPROFILE\.ssh\skilledge_hetzner"
)

$ErrorActionPreference="Stop"
Set-StrictMode -Version Latest

$ProjectRoot=(Resolve-Path -LiteralPath $ProjectRoot).Path
$Audit=Join-Path $ProjectRoot "audit_exports"
$State=Join-Path $ProjectRoot "PROJECT_STATE"
$Milestones=Join-Path $State "milestones"
New-Item -ItemType Directory -Force -Path $Audit,$Milestones|Out-Null

$stamp=Get-Date -Format "yyyyMMdd_HHmmss"
$raw=Join-Path $Audit "S10_6O_DAY7C_PRODUCTION_DEPLOY_raw_$stamp.json"
$report=Join-Path $Audit "S10_6O_DAY7C_PRODUCTION_DEPLOY_report_$stamp.txt"
$localSh=Join-Path $env:TEMP "s10_6o_day7c_deploy_$stamp.sh"
$remoteSh="/tmp/s10_6o_day7c_deploy_$stamp.sh"

$payload=""
$bytes=[Convert]::FromBase64String($payload)
$scriptText=[Text.Encoding]::UTF8.GetString($bytes).Replace("__STAMP__",$stamp)
[IO.File]::WriteAllText($localSh,$scriptText,[Text.UTF8Encoding]::new($false))

$ssh=@("-i",$SshKey,"-o","BatchMode=yes","-o","StrictHostKeyChecking=accept-new")

Write-Host ""
Write-Host "=== UPLOAD DAY 7C PRODUCTION PATCH ===" -ForegroundColor Green
& scp @ssh $localSh "${VpsHost}:$remoteSh"
if($LASTEXITCODE-ne 0){throw "Upload failed"}

Write-Host ""
Write-Host "=== DEPLOY SCOPED PATCH WITH AUTO-ROLLBACK ===" -ForegroundColor Green
Write-Host "Only candle_engine.py + stream hydration hook." -ForegroundColor Yellow
Write-Host "Only market-stream service will restart." -ForegroundColor Yellow

$out=& ssh @ssh $VpsHost "chmod 700 '$remoteSh' && '$remoteSh'; rc=`$?; rm -f '$remoteSh'; exit `$rc"
Remove-Item -LiteralPath $localSh -Force -ErrorAction SilentlyContinue
if($LASTEXITCODE-ne 0){throw "Remote deploy failed before structured result"}

$text=$out -join "`n"
$text|Set-Content -LiteralPath $raw -Encoding UTF8
$r=$text|ConvertFrom-Json

@(
 "S10.6O DAY 7C PRODUCTION DEPLOY",
 "Generated=$stamp",
 "OK=$($r.ok)",
 "CLASSIFICATION=$($r.classification)",
 "OLD_PID=$($r.oldPid)",
 "NEW_PID=$($r.newPid)",
 "PID_CHANGED=$($r.pidChanged)",
 "SYMBOL_COUNT=$($r.symbolCount)",
 "NEGATIVE_LAST_TRADE_AGE_COUNT=$($r.negativeLastTradeAgeCount)",
 "APPLIED_TRADES_GROWTH=$($r.appliedTradesGrowth)",
 "AUTO_ROLLBACK_EXECUTED=$($r.autoRollbackExecuted)",
 "ROLLBACK_SNAPSHOT=$($r.rollbackSnapshot)",
 "NOTE=$($r.note)",
 "RAW_JSON=$raw"
)|Set-Content -LiteralPath $report -Encoding UTF8

Write-Host ""
Write-Host "=== S10.6O DAY 7C DEPLOY COMPLETE ===" -ForegroundColor Green
Write-Host "OK: $($r.ok)"
Write-Host "Classification: $($r.classification)"
Write-Host "Old PID: $($r.oldPid)"
Write-Host "New PID: $($r.newPid)"
Write-Host "PID changed: $($r.pidChanged)"
Write-Host "Symbol count: $($r.symbolCount)"
Write-Host "Negative lastTradeAge count: $($r.negativeLastTradeAgeCount)"
Write-Host "Applied trades growth: $($r.appliedTradesGrowth)"
Write-Host "Auto rollback executed: $($r.autoRollbackExecuted)"
Write-Host "Rollback snapshot: $($r.rollbackSnapshot)"
Write-Host "Known limit: $($r.note)"
Write-Host "Report: $report"
Write-Host "Raw: $raw"

if(-not $r.ok){throw "Day 7C production patch failed. Verify automatic rollback."}
